window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b392d1e393218509"]={"versions": [{"id": "FIG-b392d1e393218509", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Struktur für AUTOSAR Adaptive Platform Timing Extensions (TPS_AdaptivePlatformTimingExtensions). Das Diagramm spezifiziert die Vererbungshierarchie der Ereignisauslöser-Bedingungen (<code>EventTriggeringConstraint</code>) sowie deren strukturelle Zuordnung zu Timing-Beschreibungsereignissen (<code>TimingDescriptionEvent</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>TimingConstraint::TimingConstraint</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code> und <code>Traceable</code>.</li>\n<li><code>EventTriggeringConstraint</code>: Abstrakte Spezialisierung von <code>TimingConstraint</code>.</li>\n<li>Spezialisierungen von <code>EventTriggeringConstraint</code>:</li>\n<li><code>PeriodicEventTriggering</code>: Periodische Auslösung mit festen Intervallen.</li>\n<li><code>SporadicEventTriggering</code>: Sporadische Auslösung mit Mindestabständen.</li>\n<li><code>BurstPatternEventTriggering</code>: Bündel-/Burst-Muster mit begrenzter Ereignisanzahl je Intervall.</li>\n<li><code>ConcretePatternEventTriggering</code>: Konkrete zeitliche Ereignismuster.</li>\n<li><code>ArbitraryEventTriggering</code>: Beliebige bzw. empirisch definierte Auslösemuster.</li>\n<li>Assoziation: <code>EventTriggeringConstraint</code> referenziert über die gerichtete Assoziationsrolle <code>+event</code> mit einer Multiplizität von exakt <code>1</code> ein <code>TimingDescription::TimingDescriptionEvent</code> (Paket <code>TimingDescription</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der konkreten Trigger-Klassen beschreiben deklarativ die zulässige oder beobachtete zeitliche Auftretenscharakteristik des verknüpften <code>TimingDescriptionEvent</code> zur Entwurfs- und Analysezeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel für AUTOSAR AP Timing Models: Jede <code>EventTriggeringConstraint</code>-Instanz muss zwingend genau einem <code>TimingDescriptionEvent</code> zugeordnet sein (Kardinalität <code>1</code>). Werkzeuge zur Timing-Analyse verlangen eine vollständige Auflösung der Zielreferenz <code>+event</code>.</p>"}, {"id": "FIG-d5791bf917e2cc8b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Struktur für AUTOSAR Adaptive Platform Timing Extensions (TPS_AdaptivePlatformTimingExtensions). Das Diagramm spezifiziert die Vererbungshierarchie der Ereignisauslöser-Bedingungen (<code>EventTriggeringConstraint</code>) sowie deren strukturelle Zuordnung zu Timing-Beschreibungsereignissen (<code>TimingDescriptionEvent</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>TimingConstraint</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code> und <code>Traceable</code>.</li>\n<li><code>EventTriggeringConstraint</code>: Abstrakte Spezialisierung von <code>TimingConstraint</code>.</li>\n<li>Spezialisierungen von <code>EventTriggeringConstraint</code>:</li>\n<li><code>PeriodicEventTriggering</code>: Periodische Auslösung mit festen Intervallen.</li>\n<li><code>SporadicEventTriggering</code>: Sporadische Auslösung mit Mindestabständen.</li>\n<li><code>BurstPatternEventTriggering</code>: Bündel-/Burst-Muster mit begrenzter Ereignisanzahl je Intervall.</li>\n<li><code>ConcretePatternEventTriggering</code>: Konkrete zeitliche Ereignismuster.</li>\n<li><code>ArbitraryEventTriggering</code>: Beliebige bzw. empirisch definierte Auslösemuster.</li>\n<li>Assoziation: <code>EventTriggeringConstraint</code> referenziert über die gerichtete Assoziationsrolle <code>+event</code> mit einer Multiplizität von exakt <code>1</code> ein <code>TimingDescriptionEvent</code> (Paket <code>TimingDescription</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der konkreten Trigger-Klassen beschreiben deklarativ die zulässige oder beobachtete zeitliche Auftretenscharakteristik des verknüpften <code>TimingDescriptionEvent</code> zur Entwurfs- und Analysezeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel für AUTOSAR AP Timing Models: Jede <code>EventTriggeringConstraint</code>-Instanz muss zwingend genau einem <code>TimingDescriptionEvent</code> zugeordnet sein (Kardinalität <code>1</code>). Werkzeuge zur Timing-Analyse verlangen eine vollständige Auflösung der Zielreferenz <code>+event</code>.</p>"}, {"id": "FIG-a99be852d6c2de6e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Struktur für AUTOSAR Adaptive Platform Timing Extensions (TPS_AdaptivePlatformTimingExtensions). Das Diagramm spezifiziert die Vererbungshierarchie der Ereignisauslöser-Bedingungen (<code>EventTriggeringConstraint</code>) sowie deren strukturelle Zuordnung zu Timing-Beschreibungsereignissen (<code>TimingDescriptionEvent</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>TimingConstraint</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code> und <code>Traceable</code>.</li>\n<li><code>EventTriggeringConstraint</code>: Abstrakte Spezialisierung von <code>TimingConstraint</code>.</li>\n<li>Spezialisierungen von <code>EventTriggeringConstraint</code>:</li>\n<li><code>PeriodicEventTriggering</code>: Periodische Auslösung mit festen Intervallen.</li>\n<li><code>SporadicEventTriggering</code>: Sporadische Auslösung mit Mindestabständen.</li>\n<li><code>BurstPatternEventTriggering</code>: Bündel-/Burst-Muster mit begrenzter Ereignisanzahl je Intervall.</li>\n<li><code>ConcretePatternEventTriggering</code>: Konkrete zeitliche Ereignismuster.</li>\n<li><code>ArbitraryEventTriggering</code>: Beliebige bzw. empirisch definierte Auslösemuster.</li>\n<li>Assoziation: <code>EventTriggeringConstraint</code> referenziert über die gerichtete Assoziationsrolle <code>+event</code> mit einer Multiplizität von <code>0..1</code> ein <code>TimingDescriptionEvent</code> (Paket <code>TimingDescription</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der konkreten Trigger-Klassen beschreiben deklarativ die zulässige oder beobachtete zeitliche Auftretenscharakteristik des verknüpften <code>TimingDescriptionEvent</code> zur Entwurfs- und Analysezeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel für AUTOSAR AP Timing Models: Die Zuordnung eines <code>TimingDescriptionEvent</code> über die Rolle <code>+event</code> ist optional (Kardinalität <code>0..1</code>). Eine <code>EventTriggeringConstraint</code> kann ohne gebundenes Ereignis instanziiert bzw. vorbefüllt werden; Modellierungswerkzeuge und Validatoren müssen ungebundene Trigger-Constraints tolerieren.</p>"}], "trans": [{"from": "FIG-b392d1e393218509", "to": "FIG-d5791bf917e2cc8b", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Klassenhierarchie / Namensräume: Bei der Basisklasse <code>TimingConstraint</code> wurde der vorangestellte Paketpräfix <code>TimingConstraint::</code> entfernt.</li>\n<li>Assoziation / Zielklasse: Bei der referenzierten Klasse <code>TimingDescriptionEvent</code> wurde der vorangestellte Paketpräfix <code>TimingDescription::</code> entfernt (Paketname <code>«TimingDescription»</code> verbleibt im Klassenheader).</li>\n</ul>"}, {"from": "FIG-d5791bf917e2cc8b", "to": "FIG-a99be852d6c2de6e", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziations-Kardinalität: Kardinalität der Assoziation <code>+event</code> von <code>EventTriggeringConstraint</code> zu <code>TimingDescriptionEvent</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n</ul>"}]};
